def _post_trust_proofs_consume_batch(self, tenant: str) -> None:
    # POST /v1/trust/proofs/consume-batch：批量验真并一次性
    # 消费跨系统外部谓词证明（防重放）。
    # 1) 请求体须恰为 {"items": [项...]}，数组非空且不超过 100
    #    项；空体、非法 UTF-8/JSON、非对象、键集错误、items 非
    #    数组/空/超限均 HTTP 200 按键序恰返
    #    {"results": [], "reason": "请求非法"}；
    # 2) 合法批次逐项处理、失败不短路：项须恰为单条 consume 请
    #    求（proof 对象、非空 challenge/source_tenant_id）；项
    #    结构非法 ->
    #    {"valid": false, "reason": "请求项非法"}；其余复用单条
    #    全部验真规则、顺序与 reason，失败项不写状态、不记审计；
    # 3) 验真通过后按接收租户以
    #    (source_tenant_id, issuer_did, proof_id) 判重：批内首
    #    个未消费项成功，后项、历史或并发重放 ->
    #    {"valid": false, "reason": "外部证明已消费"}（无效项不
    #    占键）；成功项键序 valid、consumption_id、consumed_at，
    #    取值同单条（consumption_id 为单项请求规范化 JSON 字节
    #    的 SHA-256 小写 hex，consumed_at 为 UTC 秒精度 Z）；顶
    #    层 200 仅含与输入等长同序的 results；
    # 4) 本批全部新消费与审计（trust.proof.consumed /
    #    trust_proof / consumption_id）同锁一次原子落盘；失败全
    #    回滚，500 仅返 {"error": "存储失败"}；与单条 consume
    #    并发每键仅一次成功，重启保持。显式空 X-Tenant-ID 由路
    #    由统一判 400。
    def _request_invalid() -> None:
        self._send_json(
            200, {"results": [], "reason": "请求非法"}
        )

    try:
        length = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(length) if length > 0 else b""
    except (ValueError, TypeError):
        _request_invalid()
        return
    except Exception:  # noqa: BLE001
        _request_invalid()
        return
    if not raw:
        _request_invalid()
        return
    try:
        data = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        _request_invalid()
        return
    if not isinstance(data, dict) or set(data) != {"items"}:
        _request_invalid()
        return
    items = data["items"]
    if (
        not isinstance(items, list)
        or not items
        or len(items) > 100
    ):
        _request_invalid()
        return

    results: List[Optional[Dict[str, Any]]] = []
    # 验真通过、待判重消费的项：(结果下标, source_tenant_id,
    # issuer_did, proof_id, consumption_id)，消费判定在全部验真
    # 完成后同锁一次完成。
    pending: List[Tuple[int, str, str, str, str]] = []
    for index, item in enumerate(items):  # 顺序处理，失败不短路
        if not self._is_trust_proof_consume_item(item):
            results.append({"valid": False, "reason": "请求项非法"})
            continue
        try:
            valid, reason = store.verify_trust_proof(tenant, item)
        except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
            results.append(
                {"valid": False, "reason": "验签过程发生内部错误"}
            )
            continue
        if not valid:
            results.append(
                {"valid": False, "reason": reason or "验签失败"}
            )
            continue
        proof = item["proof"]
        consumption_id = hashlib.sha256(
            crypto.canonicalize(item)
        ).hexdigest()
        pending.append(
            (
                index,
                item["source_tenant_id"],
                proof["issuer_did"],
                proof["proof_id"],
                consumption_id,
            )
        )
        results.append(None)  # 占位，消费判定后回填

    if pending:
        try:
            outcomes = store.consume_trust_proofs_batch(
                tenant,
                [
                    (
                        source_tenant_id,
                        issuer_did,
                        proof_id,
                        consumption_id,
                    )
                    for (
                        _,
                        source_tenant_id,
                        issuer_did,
                        proof_id,
                        consumption_id,
                    ) in pending
                ],
            )
        except StorageError:
            self._send_error(500, "存储失败")
            return
        for (index, _, _, _, consumption_id), (
            consumed,
            consumed_at,
        ) in zip(pending, outcomes):
            if consumed:
                results[index] = {
                    "valid": True,
                    "consumption_id": consumption_id,
                    "consumed_at": consumed_at,
                }
            else:
                results[index] = {
                    "valid": False,
                    "reason": "外部证明已消费",
                }
    self._send_json(200, {"results": results})

